  "A policy is a set of limits. It only runs on the ACs you attach it to (open an AC › Alert policies). Every AC also has the default policy.": "ポリシーは、しきい値のまとまりです。適用したエアコンでだけ動作します（エアコンを開く › アラートポリシー）。どのエアコンにも既定のポリシーが適用されます。",
