  "Covers ventilation and the usual causes of breakdowns. It is attached to every AC and cannot be detached or edited, but the account owner can switch each rule on or off for your account (all your ACs); members see the rules read-only. Ask HQ if a limit should change.": "換気と、故障のおもな原因を対象にしています。すべてのエアコンに適用され、取り外しも編集もできませんが、アカウントのオーナーは、ルールごとにオン/オフ（お客様のすべてのエアコンに対して）を切り替えられます。メンバーは閲覧のみです。しきい値を変えたいときは本部にご相談ください。",
