  "Nothing is booked yet — you will see “Scheduled” once a time is confirmed. Any time outside your 3 options needs your approval.": "まだ何も確定していません。時刻が確定すると「予定済み」と表示されます。3つの候補以外の時刻は、お客様の承認が必要です。",
  "Declined": "辞退済み",
