  "A note can’t change the visit time or the technician. To move the visit, write it here — HQ sends you a new time to accept. Notes are kept in the job history.": "メモでは、訪問の時刻や技術者を変更できません。訪問を動かしたいときはここに書いてください。本部が承諾用の新しい時刻を送ります。メモは作業履歴に残ります。",
