  "Read-only — HQ sets up properties, floors, rooms and units. You can rename any location with its edit button or Rename; nothing else here changes the structure.": "閲覧のみです — 物件、フロア、部屋、ユニットは本部が設定します。場所の名前は、編集ボタンまたは名前の変更から変えられます。それ以外では構成は変わりません。",
