  "Select a room to see its air conditioners": "部屋を選ぶと、その部屋のエアコンが表示されます",
  "Floor → Room → Air conditioner. Each room lists every AC inside it; open one to control it.": "フロア → 部屋 → エアコン。各部屋にはその中のすべてのエアコンが並びます。開くと操作できます。",
