  "Moving a unit into a room is done in HQ’s unit register — contact HQ.": "ユニットを部屋に移す作業は、本部のユニット台帳で行います — 本部にご連絡ください。",
  "Unassigned units ({n})": "未割り当てのユニット（{n}）",
