  "Air conditioners in this {kind} ({n})": "この{kind}のエアコン（{n}）",
  "Each AC has its own control screen; Group control sends one setting to several ACs in a space. Unit membership is managed in HQ’s unit register.": "各エアコンには専用の操作画面があります。グループ操作では、スペース内の複数のエアコンに同じ設定を送れます。ユニットの所属は、本部のユニット台帳で管理されています。",
  "Each AC has its own control screen. Unit membership is managed in HQ’s unit register.": "各エアコンには専用の操作画面があります。ユニットの所属は、本部のユニット台帳で管理されています。",
