  "“{name}” already exists there — choose another name. Your input is kept.": "「{name}」はすでにそこにあります — 別の名前にしてください。入力内容は残っています。",
  "Someone renamed it in the meantime — the tree now shows the current name. Your input is kept.": "その間に他の人が名前を変更しました — ツリーには現在の名前が表示されています。入力内容は残っています。",
  "Someone changed this AC in the meantime — the page now shows its current name. Your input is kept.": "その間に他の人がこのエアコンを変更しました — ページには現在の名前が表示されています。入力内容は残っています。",
  "Save name": "名前を保存",
  "Only the name changes. Floors, rooms and units stay as they are — HQ manages the structure.": "変わるのは名前だけです。フロア、部屋、ユニットはそのままで、構成は本部が管理します。",
