  "Keep": "変更しない",
  "Each AC gets its own command and confirmation (same as single control). Offline ACs are skipped; restrictions such as a minimum temperature still apply per AC. One space only · owner role only.": "各エアコンに個別のコマンドと確認があります（単体の操作と同じです）。オフラインのエアコンはスキップされ、下限温度などの利用制限もエアコンごとに適用されます。対象は1つのスペースのみ · オーナーのロールのみ。",
  "Retry failed ACs": "失敗したエアコンを再試行",
