  "After sending, each card shows Sending → Confirmed / Failed. Failed ACs can be retried one by one; there is no rollback across ACs.": "送信後、各カードに「送信中 → 確認済み / 失敗」と表示されます。失敗したエアコンは1台ずつ再試行できます。エアコンをまたいだ取り消しはありません。",
