  "When {days} at {start} → {startAction}. At {end} (next day) → {endAction}.{onlyIf}": "{days} の {start} に → {startAction}。翌日の {end} に → {endAction}。{onlyIf}",
  "When {days} at {start} → {startAction}. At {end} → {endAction}.{onlyIf}": "{days} の {start} に → {startAction}。{end} に → {endAction}。{onlyIf}",
  "you arrive at {place}": "{place} に到着したとき",
  "everyone leaves {place}": "全員が {place} を離れたとき",
