  "the outdoor temperature is {op} {value}°C": "外気温が {op} {value}°C のとき",
  "When {when} → {action}.{onlyIf}": "{when} → {action}。{onlyIf}",
  " Only if {conditions}.": "ただし {conditions} の場合のみ。",
  "Weekdays are the start day. At run time the automation is re-checked (permissions, capabilities, restrictions).": "曜日は開始日です。実行時に、自動化は再確認されます（権限、機能、利用制限）。",
  "Does not run if occupancy data is missing — missing data never counts as a match.": "在室のデータがない場合は実行されません — データがないことは一致とは見なされません。",
  "Does not run if consent is withdrawn or location data is missing.": "同意が撤回されている場合や、位置情報がない場合は実行されません。",
  "A demo estimate of your routine — no real behaviour history is collected.": "ルーチンのデモ用の推定です — 実際の行動履歴は収集していません。",
  "Does not run if weather data is missing — the evaluation is skipped with a reason.": "天気のデータがない場合は実行されません — 評価は理由とともにスキップされます。",
