  "Another automation": "別の自動化",
  "{when} — not sent": "{when} — 送信されません",
  "Nothing would be sent: {reason}": "何も送信されません: {reason}",
  "no reason": "理由なし",
  "Not recorded": "記録なし",
  "No location consent record exists for your account — location automations cannot be used.": "お客様のアカウントに位置情報の同意の記録がないため、位置情報による自動化は使えません。",
  "Granted": "同意済み",
  "Revoked": "撤回済み",
  "Not granted": "未同意",
  "Granted {when} · used only by {n} location automation · demo location events (no real GPS history).": "{when} に同意 · 位置情報による自動化 {n} 件でのみ使用 · デモの位置情報イベント（実際の GPS 履歴はありません）。",
  "Granted {when} · used only by {n} location automations · demo location events (no real GPS history).": "{when} に同意 · 位置情報による自動化 {n} 件でのみ使用 · デモの位置情報イベント（実際の GPS 履歴はありません）。",
  "Withdrawn {when} · {n} location automation was turned off and will not run. Granting consent again does NOT turn them back on automatically — you re-enable each one. Manual control is unaffected.": "{when} に撤回 · 位置情報による自動化 {n} 件がオフになり、実行されません。同意を再度付与しても自動ではオンに戻りません — 1件ずつオンにしてください。手動操作には影響しません。",
  "Withdrawn {when} · {n} location automations were turned off and will not run. Granting consent again does NOT turn them back on automatically — you re-enable each one. Manual control is unaffected.": "{when} に撤回 · 位置情報による自動化 {n} 件がオフになり、実行されません。同意を再度付与しても自動ではオンに戻りません — 1件ずつオンにしてください。手動操作には影響しません。",
  "Withdrawn {when} · location automations cannot run until you grant it again. Manual control and schedules are unaffected.": "{when} に撤回 · 再度同意するまで、位置情報による自動化は実行できません。手動操作とスケジュールには影響しません。",
  "Location automations need your consent. It is used only for arrival/departure automations — demo location events, no real GPS history.": "位置情報による自動化には、同意が必要です。到着・外出の自動化にのみ使用し、デモの位置情報イベントで、実際の GPS 履歴はありません。",
