  "Open a window or run your ventilation fan, then log it — the record is kept in this room’s ventilation history.": "窓を開けるか換気扇を回し、その内容を記録してください — 記録はこの部屋の換気履歴に残ります。",
  "{unit} has no fresh-air function, so nothing is sent to the AC — open a window, then log what you did.": "{unit} には外気導入機能がないため、エアコンには何も送信されません — 窓を開けて、行ったことを記録してください。",
  "Neither CO2 nor PM2.5 has a current reading — no advice is given from missing data.": "CO2 も PM2.5 も現在の測定値がありません — データがないため、アドバイスは出ません。",
  "You can still log a manual ventilation.": "手動の換気は引き続き記録できます。",
  "Manual ventilation: {unit} has no fresh-air function, so open a window or use a fan and log what you did — nothing is sent to the AC.": "手動の換気: {unit} には外気導入機能がないため、窓を開けるか扇風機を使い、行ったことを記録してください — エアコンには何も送信されません。",
  "Manual ventilation": "手動の換気",
  "Open a window or use a fan. {unit} has no fresh-air function, so nothing is sent to the AC — just log what you did.": "窓を開けるか、扇風機を使ってください。{unit} には外気導入機能がないため、エアコンには何も送信されません — 行ったことだけ記録してください。",
  "After opening a window or running your ventilation fan, log it — nothing is sent to the AC or to HQ.": "窓を開けたり換気扇を回したりしたら、記録してください — エアコンにも本部にも何も送信されません。",
  "{guidance} — PM2.5 {value} µg/m³ in {room} (≥ 35 µg/m³ guide). Request a filter clean from Maintenance.": "{guidance} — {room} の PM2.5 は {value} µg/m³ です（目安 35 µg/m³ 以上）。メンテナンスからフィルター清掃を依頼してください。",
