  "Delegation ended — only the minimal history of your company’s decisions stays visible. Unit data and entry instructions are no longer shown.": "委任は終了しました — 貴社の判断の最小限の履歴だけが表示されます。ユニットのデータと入室の案内は、もう表示されません。",
