  "offer": "オファー",
  "accepted": "承諾済み",
  "HQ asked the client about your proposed time ({slot} · {name}) — the offer stays reserved for you; Accept is disabled until it is answered.": "本部が、提案された時刻（{slot} · {name}）について顧客に確認しました — オファーは貴社のために保留され、回答があるまで「承諾」は使えません。",
  "Your proposed time is with HQ ({slot} · {name}) — the offer stays reserved for you; Accept is disabled until it is answered.": "提案した時刻は本部が確認中です（{slot} · {name}）— オファーは貴社のために保留され、回答があるまで「承諾」は使えません。",
  "The client approved your proposed time — the visit is now {slot}. Accept the offer to continue.": "顧客が提案した時刻を承認しました — 訪問は {slot} になりました。続けるには、オファーを承諾してください。",
  "Your time change was not taken — the agreed time stays {slot}. Accept or decline.": "時刻の変更は採用されませんでした — 合意した時刻は {slot} のままです。承諾または辞退してください。",
