  "Technician (own company, active, qualified)": "技術者（自社・有効・資格あり）",
  "Choose a technician": "技術者を選んでください",
  "Choose another technician or a later end": "別の技術者か、あとの終了時刻を選んでください",
  "No technicians in your company yet — add them in Team & capacity.": "貴社にはまだ技術者がいません — チームと対応可能数で追加してください。",
  "Only active technicians of your company are listed; eligibility is checked again on save.": "表示されるのは貴社の有効な技術者だけです。適格性は保存時にもう一度確認されます。",
  "Free hours are in Kuala Lumpur time (Asia/Kuala_Lumpur).": "空き時間はクアラルンプール時間です（Asia/Kuala_Lumpur）。",
