  "Work end (same or later)": "作業の終了（同じかあと）",
  "Times in {zone}.": "時刻は {zone} です。",
  "The end must be at or after the current end": "終了は、現在の終了と同じかそれ以降にしてください",
  "Visit time (agreed with the client)": "訪問時刻（顧客と合意済み）",
  "Fixed. A different time needs the client’s approval via HQ.": "確定済みです。別の時刻には、本部経由で顧客の承認が必要です。",
  "Reason for reassignment (required, 1–1000)": "再割り当ての理由（必須、1～1000文字）",
  "Reason (optional, kept with the change)": "理由（任意、変更とともに保存されます）",
  "A reason is required while the work is under way": "作業中は理由が必要です",
  "tech-external-a is on sick leave from today.": "tech-external-a は、今日から病気休暇です。",
  "On save, {current} loses action access immediately. The job keeps its state; {name} continues in a new draft version and the original report authorship is kept.": "保存すると、{current} はすぐに操作の権限を失います。作業の状態はそのままで、{name} は新しい下書きの版で続け、元の報告書の作成者も保たれます。",
  "the current technician": "現在の技術者",
  "The current technician accepted the assignment": "現在の技術者が割り当てを承諾しました",
  "Waiting for the current technician to accept the assignment.": "現在の技術者が割り当てを承諾するのを待っています。",
  "The technician could do {slot} instead — a different time needs the client’s approval via HQ.": "技術者は代わりに {slot} に対応できます — 別の時刻には、本部経由で顧客の承認が必要です。",
  "No technician of your company can take this time (busy, unavailable or not qualified). Free a technician in Team & capacity, or ask HQ to agree another time with the client.": "貴社のどの技術者も、この時間は対応できません（予定あり、対応不可、または資格なし）。チームと対応可能数で技術者の予定を空けるか、本部に顧客と別の時刻を合意するよう依頼してください。",
  "No overlapping confirmed schedule for {name} in this window.": "この期間に {name} の確定済みの予定との重なりはありません。",
  "{name}: {reason} — saving is refused.": "{name}: {reason} — 保存は拒否されました。",
  "Save new slot": "新しい枠を保存",
  "Reassigning a job already in progress requires a reason and immediately revokes the previous technician’s access.": "すでに作業中の作業を再割り当てするには理由が必要で、前の技術者のアクセスはすぐに取り消されます。",
  "Technician assigned — waiting for acceptance": "技術者を割り当てました — 承諾待ち",
  "Assignment changed": "割り当てを変更しました",
  "Assigned {name} for {slot}. The technician must accept the assignment; HQ and the technician are notified.": "{slot} に {name} を割り当てました。技術者は割り当てを承諾する必要があります。本部と技術者に通知されます。",
  "Changed to {name} for {slot}. The technician must accept the assignment; HQ and the technician are notified.": "{slot} の担当を {name} に変更しました。技術者は割り当てを承諾する必要があります。本部と技術者に通知されます。",
  "Confirmed assignment": "確定した割り当て",
  "This proposal": "この提案",
  "Leave / unavailable": "休暇 / 対応不可",
  "No available hours": "対応可能な時間がありません",
  "Only own-company technicians are shown. Days and times in Kuala Lumpur time (Asia/Kuala_Lumpur). A time that overlaps a confirmed block is refused on save.": "表示されるのは貴社の技術者だけです。日付と時刻はクアラルンプール時間です（Asia/Kuala_Lumpur）。確定済みの時間帯と重なる時刻は、保存時に拒否されます。",
  "Members": "メンバー",
  "Certifications": "資格証明書",
  "Roster not found": "名簿が見つかりません",
  "You can only see {company}’s own technicians. Changing the company ID in the URL does not reveal another company’s roster.": "表示できるのは {company} 自身の技術者だけです。URL の会社 ID を変えても、ほかの会社の名簿は表示されません。",
  "Back to my team": "自分のチームに戻る",
  "your company": "貴社",
  "No technicians": "技術者はいません",
