  "{n} active": "有効 {n} 人",
  "Unavailable days": "対応不可日",
  "No {company} technicians hold this qualification": "この資格を持つ {company} の技術者はいません",
  "Qualifications are granted by HQ: upload a renewed certificate under Certifications. Accounts are managed in Users.": "資格は本部が付与します。資格証明書で更新した証明書をアップロードしてください。アカウントはユーザーで管理します。",
  "utilization": "稼働率",
  "Utilization = assigned hours ÷ configured available hours (4 h / 8 h = 50%). Undefined available hours show “—”, not 0%. Accounts are managed in Users.": "稼働率 = 割り当て済みの時間 ÷ 設定した対応可能時間（4 時間 / 8 時間 = 50%）。対応可能時間が定義されていない場合は、0% ではなく「—」と表示します。アカウントはユーザーで管理します。",
  "Qualifications": "資格",
  "1 expired member hidden (Active only).": "期限切れのメンバー 1 人を非表示にしています（有効なもののみ）。",
  "{n} expired members hidden (Active only).": "期限切れのメンバー {n} 人を非表示にしています（有効なもののみ）。",
  "Expired memberships ({names}) are listed but cannot be selected for assignment. A new access end is set in Users.": "期限切れのメンバーシップ（{names}）は一覧に表示されますが、割り当てには選べません。新しいアクセスの終了日は、ユーザーで設定します。",
  "Qualifications are granted by HQ from your technicians’ certificates; accounts are managed in Users.": "資格は、技術者の資格証明書をもとに本部が付与します。アカウントはユーザーで管理します。",
  "Available": "対応可能",
  "Team utilization": "チームの稼働率",
  "Free hours {day}": "{day} の空き時間",
  "Sat/Sun have no configured available hours, so utilization shows “—”.": "土日は対応可能時間が設定されていないため、稼働率は「—」と表示されます。",
  "Days and hours are in Kuala Lumpur time (Asia/Kuala_Lumpur).": "日付と時間は、クアラルンプール時間です（Asia/Kuala_Lumpur）。",
  "Add unavailable days": "対応不可日を追加",
  "Save": "保存",
  "All technicians (public holiday)": "すべての技術者（祝日）",
  "Note (optional)": "メモ（任意）",
  "Conflicts with 1 confirmed assignment: {list}. Saving keeps the assignment — reassign it in Schedule & assignments.": "確定済みの割り当て 1 件と重なります: {list}。保存しても割り当ては残ります — スケジュールと割り当てで再割り当てしてください。",
  "Conflicts with {n} confirmed assignments: {list}. Saving keeps the assignments — reassign them in Schedule & assignments.": "確定済みの割り当て {n} 件と重なります: {list}。保存しても割り当ては残ります — スケジュールと割り当てで再割り当てしてください。",
  "Unavailable days set the technician’s available hours to 0 for those dates, so utilization and the lists of who can take a visit skip them. For a public holiday of the whole team choose Public holiday and All technicians.": "対応不可日は、その日付の技術者の対応可能時間を 0 にするため、稼働率や、訪問を担当できる人の一覧から外れます。チーム全体の祝日には、「祝日」と「すべての技術者」を選んでください。",
  "The days are Kuala Lumpur days.": "日付はクアラルンプールの日付です。",
  "Unavailable days saved — the available hours of those days are 0.": "対応不可日を保存しました — その日の対応可能時間は 0 です。",
  "Unavailable days saved — 1 confirmed assignment overlaps them; reassign it in Schedule & assignments.": "対応不可日を保存しました — 確定済みの割り当て 1 件と重なっています。スケジュールと割り当てで再割り当てしてください。",
  "Unavailable days saved — {n} confirmed assignments overlap them; reassign them in Schedule & assignments.": "対応不可日を保存しました — 確定済みの割り当て {n} 件と重なっています。スケジュールと割り当てで再割り当てしてください。",
  "Upcoming unavailable days": "今後の対応不可日",
