  "Remove unavailable days of {who}, {days}": "{who} の対応不可日 {days} を削除",
  "Days that have passed stay recorded. Removing days makes the technician available for visits on them again.": "過ぎた日は記録に残ります。日を削除すると、その日に技術者が再び訪問を担当できるようになります。",
  "Remove unavailable days": "対応不可日を削除",
