  "Blocks": "ブロック",
  "Certificates are checked when you assign a technician. An expired certificate makes the technician ineligible for jobs that need it; nothing is revoked automatically before expiry.": "資格証明書は、技術者を割り当てるときに確認されます。期限切れの資格証明書があると、それを必要とする作業の対象外になります。期限の前に自動で取り消されることはありません。",
