  "Your time is free for other jobs. The report, the unit and its devices stay with HQ and the customer.": "あなたの時間は、ほかの作業に使えます。報告書、ユニット、そのデバイスは、本部と顧客のもとに残ります。",
  "The job was cancelled, so the job details and the unit are no longer shown to you.": "作業がキャンセルされたため、作業の詳細とユニットは表示されなくなりました。",
  "Your work window ended, or HQ or your coordinator changed the assignment, so the job details and the unit are no longer shown to you.": "作業時間が終了したか、本部または担当者が割り当てを変更したため、作業の詳細とユニットは表示されなくなりました。",
  "Normal": "正常",
