  "Can’t make this time…": "この時刻は対応できません…",
  "New assignment for {window}. Accepting tells your coordinator and HQ you will attend; the client then sees your name.": "{window} の新しい割り当てです。承諾すると、担当者と本部に出席することが伝わり、顧客にはあなたの名前が表示されます。",
  "You said you can’t make this time (“{reason}”). Your coordinator reassigns the job or asks the client for another time.": "この時刻は対応できないと回答しました（「{reason}」）。担当者が作業を再割り当てするか、顧客に別の時刻を依頼します。",
  "You said you can’t make this time. Your coordinator reassigns the job or asks the client for another time.": "この時刻は対応できないと回答しました。担当者が作業を再割り当てするか、顧客に別の時刻を依頼します。",
  "Start job (check in)": "作業を開始（チェックイン）",
  "Read-only until the window opens at {time} — Start is disabled before then.": "{time} に作業時間が始まるまで読み取り専用です — それまで「開始」は使えません。",
  "The work window has ended — ask your coordinator to reschedule.": "作業時間が終了しました — 担当者に日程の変更を依頼してください。",
  "On site: Start job opens Check in (location + unit QR); checking in starts the work.": "現地では、「作業を開始」でチェックイン（位置情報とユニットの QR）が開き、チェックインすると作業が始まります。",
  "On hold by HQ — saving and submitting are blocked. Your saved draft is kept; continue when HQ resumes the job.": "本部が保留中です — 保存と提出はできません。保存済みの下書きは残ります。本部が作業を再開したら続けてください。",
  "Submitted v{version} — read-only, awaiting quality review.": "v{version} を提出しました — 読み取り専用で、品質レビュー待ちです。",
  "Accepted — the job is completed and the report is visible to the customer.": "承諾されました — 作業は完了し、報告書は顧客に表示されます。",
  "Rework resumed — continue in the new draft": "やり直しを再開しました — 新しい下書きで続けてください",
  "Resume rework": "やり直しを再開",
  "Returned for rework — “{reason}”. Resume to continue as a new draft version; the returned version stays as it was.": "やり直しのため差し戻されました —「{reason}」。再開すると新しい下書きの版で続けられます。差し戻された版はそのまま残ります。",
  "Returned for rework. Resume to continue as a new draft version; the returned version stays as it was.": "やり直しのため差し戻されました。再開すると新しい下書きの版で続けられます。差し戻された版はそのまま残ります。",
  "The work window ended — unsaved input was discarded and the job can no longer be edited. Ask your coordinator.": "作業時間が終了しました — 未保存の入力は破棄され、この作業は編集できなくなりました。担当者に連絡してください。",
