  "Automatic resolution needs a remeasurement {recovery} — or a reason below with alert.resolve.": "自動で解決するには、再測定が {recovery} になる必要があります — または、下で理由を添えて alert.resolve で解決します。",
  "No remeasurement resolves this alert — it has no policy. Resolve it with a reason below with alert.resolve.": "再測定ではこのアラートは解決されません — ポリシーがないためです。下で理由を添えて alert.resolve で解決してください。",
  "Resolved {time} — {reason}.": "{time} に解決 — {reason}。",
  "Completing the job alone never resolves an alert. If the condition returns, a new alert is created that links back to alert {id}.": "作業の完了だけでは、アラートは解決されません。状態が再発した場合は、アラート {id} に紐づく新しいアラートが作成されます。",
  "If it recurs after it is resolved, a new alert is created that links back to this one.": "解決後に再発した場合は、このアラートに紐づく新しいアラートが作成されます。",
  "Not resolved — you don’t have alert.resolve. The alert resolves automatically once a remeasurement stays {recovery}, or ask a permitted user.": "解決されていません — alert.resolve の権限がありません。再測定が {recovery} のままになると、アラートは自動で解決されます。または、権限のあるユーザーに依頼してください。",
  "Not resolved — you don’t have alert.resolve. Ask a permitted user to resolve it.": "解決されていません — alert.resolve の権限がありません。権限のあるユーザーに解決を依頼してください。",
