  "No new notice: one about {name} already went out — within the cooldown, or for its alert that is still open.": "新しい通知なし: {name} についてはすでに通知済みです — クールダウン中か、まだ未対応のアラートがあります。",
  "No alert: the reading does not count (missing, stale or not valid).": "アラートなし: この測定値は対象外です（欠測、古い、または無効）。",
