  "No alert: {value} {unit} meets {op} {threshold} {unit}, but not within the active hours.": "アラートなし: {value} {unit} は {op} {threshold} {unit} を満たしていますが、有効な時間帯の外です。",
  "No alert: {value} {unit} does not meet {op} {threshold} {unit}.": "アラートなし: {value} {unit} は {op} {threshold} {unit} を満たしていません。",
