  "Test with demo data": "デモデータでテスト",
  "Evaluates the saved policy against a synthetic reading on one of its units (automations.simulate). The reading counts as lasting the policy's duration; nothing is stored.": "保存済みのポリシーを、そのユニットの1つに対する合成の測定値で評価します（automations.simulate）。測定値は、ポリシーの継続時間の間続いたものとして扱われ、何も保存されません。",
