  "Saving changes affects all units. Customers and HQ can add their own policies on top; this rule cannot be detached from a unit.": "保存すると、すべてのユニットに影響します。顧客と本部は、その上に独自のポリシーを追加できます。このルールをユニットから取り外すことはできません。",
  "{metric} is not a metric a customer policy can watch, so this rule cannot be copied.": "{metric} は、顧客のポリシーで監視できる指標ではないため、このルールはコピーできません。",
