  "Policies belong to the customer. Each unit picks which of them it carries (unit edit › Alert policies). Air-quality limits are alert policies too.": "ポリシーは顧客に属します。各ユニットが、どれを使うかを選びます（ユニットの編集 › アラートポリシー）。空気質のしきい値もアラートポリシーです。",
  "New policy for {name}": "{name} の新しいポリシー",
  "Made by": "作成者",
  "All {n}": "すべて {n}",
  "A row opens the policy editor (Alert policies › Policies). The default policy is on every unit; its rules can be switched per customer but it cannot be detached.": "行を開くと、ポリシーの編集画面（アラートポリシー › ポリシー）が開きます。既定のポリシーはすべてのユニットにあり、ルールは顧客ごとに切り替えられますが、取り外すことはできません。",
  "Default policy rules for {name}": "{name} の既定のポリシーのルール",
  "Limits are edited once for every customer (Alert policies › Default policy). Here you switch each rule on or off for this customer — the customer’s owner can do the same in the customer app.": "しきい値の編集は、すべての顧客に対して一度だけ行います（アラートポリシー › 既定のポリシー）。ここでは、この顧客に対して各ルールをオン/オフにします — 顧客のオーナーも、顧客アプリで同じことができます。",
