  "A parent in another property, or a parent change that creates a cycle, is rejected with VALIDATION.": "別の物件の親や、循環が生じる親の変更は、VALIDATION で拒否されます。",
  "Only the name changes; units, child locations and history stay attached. The customer sees the new name immediately.": "変わるのは名前だけで、ユニット、下位の場所、履歴はそのまま残ります。顧客には新しい名前がすぐに表示されます。",
  "1–120 characters, unique among its siblings. Saved with a version check — an older version is CONFLICT.": "1～120文字、同じ階層の中で重複しないこと。バージョン確認つきで保存されます — 古いバージョンは CONFLICT になります。",
