  "Keeps the unit ID; version {from} → {to}. Alert policies stay attached to the unit.": "ユニット ID は保たれます。バージョン {from} → {to}。アラートポリシーはユニットに適用されたままです。",
  "Delete unit": "ユニットを削除",
  "Removes the unit from lists, totals and candidates. Its history is kept (archived), and its active automations are switched off.": "ユニットを、一覧、合計、候補から外します。履歴は保存され（アーカイブ）、有効な自動化はオフになります。",
