  "A unit that never had a contract, a job or an IoT device can be removed completely; any other unit is refused and has to be deleted as above.": "契約、作業、IoT デバイスが一度もなかったユニットは、完全に削除できます。それ以外のユニットは拒否され、上記の方法で削除する必要があります。",
