  "No audit entries match this period, actor, target, correlation ID or result.": "この期間、実行者、対象、相関 ID、または結果に一致する監査の記録はありません。",
  "No entries with the result {result}": "結果が {result} の記録はありません",
  "Pending and failed results belong to device commands: a command waits as pending, and its result follows under the same correlation ID.": "「保留中」と「失敗」はデバイスのコマンドに属します。コマンドは保留中として待機し、結果は同じ相関 ID のもとで続きます。",
