  "Load command": "コマンドを読み込む",
  "Links open the existing detail screens, and each checks your permission there. “Load command” reads the command only when you click it. Audit entries cannot be edited, deleted or exported.": "リンクは既存の詳細画面を開き、各画面であなたの権限が確認されます。「コマンドを読み込む」は、クリックしたときだけコマンドを読み取ります。監査の記録は、編集、削除、出力できません。",
  "You may not read this command — it needs control.execute, restriction.read, restriction.override or automation.policy.read.": "このコマンドは読み取れません — control.execute、restriction.read、restriction.override、または automation.policy.read が必要です。",
  "This command is outside your scope or no longer exists.": "このコマンドは、あなたの範囲外か、もう存在しません。",
  "The command could not be loaded — try again.": "コマンドを読み込めませんでした — もう一度お試しください。",
  "this entry’s target": "この記録の対象",
  "same correlation ID": "同じ相関 ID",
  "exception until {time}": "{time} まで例外",
  "{state} — as this entry recorded it": "{state} — この記録に記録されたとおり",
  "version {from} → {to}": "バージョン {from} → {to}",
  "Correlation trace": "相関のトレース",
  "Pending is shown on its own; the final result is a new entry with the same correlation ID. Earlier entries are never edited.": "「保留中」は単独で表示されます。最終結果は、同じ相関 ID の新しい記録です。以前の記録が編集されることはありません。",
  "Load more": "さらに読み込む",
  "System": "システム",
  "Period must be start < end, at most 366 days": "期間は、開始 < 終了で、366日以内にしてください",
  "Read-only · entries are appended only by business events": "閲覧のみ · 記録は、業務上のイベントによってのみ追記されます",
  "No create, edit, or delete here — the log is append-only. Secrets and contacts in before/after are masked. Filters are kept in the URL; reasons and values never are.": "ここでは、作成、編集、削除はできません — ログは追記のみです。変更前後の機密情報と連絡先はマスクされます。フィルターは URL に保持されますが、理由と値は保持されません。",
  "No create, edit, or delete here. Secrets and contacts in before/after are masked. This browser demo does not guarantee tamper-proof storage.": "ここでは、作成、編集、削除はできません。変更前後の機密情報と連絡先はマスクされます。このブラウザのデモでは、改ざん防止の保存は保証されません。",
  "Actor: All": "実行者: すべて",
  "Target: All": "対象: すべて",
