  "That entry is not in these results": "その記録は、この結果にありません",
  "Change the filters or load more to open it.": "フィルターを変更するか、さらに読み込んで開いてください。",
  "Nothing was searched": "検索されていません",
  "The period must start before it ends and cover at most 366 days. Earlier results are cleared so they are not mistaken for this search.": "期間は、開始が終了より前で、366日以内にしてください。以前の結果は、この検索のものと間違えないよう消去されます。",
  "No entries with this correlation ID": "この相関 ID の記録はありません",
  "This looks the same for an ID that does not exist and for one outside your managed scope. Clear the correlation ID or widen the period.": "存在しない ID の場合も、管理範囲外の ID の場合も、同じように表示されます。相関 ID を消去するか、期間を広げてください。",
  "Select a device…": "デバイスを選択…",
  "The devices you may see. Events load only after you pick a device — there is no “all devices” view.": "表示できるデバイスです。デバイスを選んでからイベントを読み込みます — 「すべてのデバイス」の表示はありません。",
  "Pick a device": "デバイスを選んでください",
  "That device is not in your list": "そのデバイスは、お客様の一覧にありません",
  "It does not exist or is outside your scope. Pick one of your devices.": "存在しないか、範囲外です。一覧のデバイスから選んでください。",
  "Choose a device above to see its connection, power and tamper events.": "上でデバイスを選ぶと、接続、電力、不正開封のイベントが表示されます。",
