  "{n} more — type to narrow the list": "ほか {n} 件 — 入力して絞り込んでください",
  "Choosing a role only pre-checks its typical permissions; every permission below stays editable. The client role is not offered here.": "ロールを選ぶと、そのロールの一般的な権限があらかじめチェックされるだけです。下のすべての権限は編集できます。顧客のロールは、ここでは選べません。",
  "Write includes Read (Read is locked on while Write is on). Actions are independent of Read/Write — e.g. billing.write issues invoices but confirming payments needs billing.payment; mrv.write drafts reports but recording a review needs mrv.review and changing emission factors needs mrv.factors.": "「編集」には「閲覧」が含まれます（編集がオンの間、閲覧はオンのまま固定されます）。操作は、閲覧/編集とは独立しています — たとえば billing.write は請求書を発行しますが、支払いの確認には billing.payment が必要です。mrv.write はレポートの下書きを作りますが、レビューの記録には mrv.review、排出係数の変更には mrv.factors が必要です。",
  "Billing months from": "請求月の開始",
  "Billing months to": "請求月の終了",
  "All months": "すべての月",
  "The first month must not be after the last": "最初の月は、最後の月より後にはできません",
  "Paid in period": "期間中に支払い済み",
  "Related restrictions": "関連する利用制限",
  "This invoice is a cause of this restriction. Once all of its cause invoices are paid, it moves to “release requested”. Its state and units are on the Restrictions screen (restriction.read).": "この請求書は、この利用制限の原因です。原因となった請求書がすべて支払い済みになると、利用制限は「解除を依頼済み」に移ります。状態とユニットは、利用制限の画面（restriction.read）にあります。",
  "This invoice is a cause of these restrictions. Once all cause invoices of a restriction are paid, it moves to “release requested”. Their states and units are on the Restrictions screen (restriction.read).": "この請求書は、これらの利用制限の原因です。ある利用制限の原因となった請求書がすべて支払い済みになると、その利用制限は「解除を依頼済み」に移ります。状態とユニットは、利用制限の画面（restriction.read）にあります。",
  "from {month}": "{month} から",
