  "Contractor / statement": "協力会社 / 明細",
  "Drafts come from the jobs whose report HQ accepted in that month, priced by each contractor's rate card. Generating again rebuilds the drafts; approved and paid statements stay as they are.": "下書きは、その月に本部が報告書を承諾した作業から、各協力会社の料金表で価格を設定して作成されます。もう一度生成すると、下書きが作り直されます。承認済みと支払い済みの明細は、そのままです。",
  "Generate drafts": "下書きを生成",
  "Generate the drafts of a month that has ended.": "終了した月の下書きを生成してください。",
  "It does not exist, or the period, contractor or status filter hides it.": "存在しないか、期間、協力会社、または状態のフィルターで非表示になっています。",
  "Kuala Lumpur months; the last one that has ended is {month}": "クアラルンプールの月です。最後に終了した月は {month} です",
  "Mark paid unlocks on the pay date ({date}). Payouts need billing.payment; every action is audited.": "「支払い済みにする」は、支払日（{date}）に使えるようになります。支払いには billing.payment が必要で、すべての操作は監査されます。",
  "Net": "正味",
  "No statement matches these filters.": "これらのフィルターに一致する明細はありません。",
