  "Statements · {period}": "明細 · {period}",
  "That statement is not in this list": "その明細は、この一覧にありません",
  "Drafts are generated on the 1st from review-accepted jobs × the contractor's rate card. Approve → the contractor sees it; Mark paid after the bank transfer (manual in this demo).": "下書きは、1日に、レビューで承諾された作業 × 協力会社の料金表から生成されます。承認 → 協力会社に表示されます。銀行振込のあとに「支払い済みにする」（このデモでは手動）。",
  "1 active restriction": "有効な利用制限 1 件",
