  "Reading a notification is separate from resolving the linked alert. Maintenance scheduling events (new request, time proposed, accepted/declined, new offer, new assignment) appear here for the role that has to act.": "通知を読んでも、紐づくアラートが解決されるわけではありません。メンテナンスの日程のイベント（新しい依頼、時刻の提案、承諾/辞退、新しいオファー、新しい割り当て）は、対応が必要なロールに、ここに表示されます。",
