  "Core API seed · generation 1": "コア API のシード · 世代 1",
  "The demo seed in fixture-contract.json is the source of truth. The Core API demo runs this one scenario; the simulator switch is in the browser demo.": "fixture-contract.json のデモのシードが正です。コア API のデモは、このシナリオだけを実行します。シミュレーターの切り替えは、ブラウザのデモにあります。",
