  "Account deleted": "アカウントを削除しました",
  "Delete the account of {name}? The person and their sign-in are deleted with it. Only an account that never acted, with no assignment or certificate, can be deleted; otherwise revoke the access.": "{name} のアカウントを削除しますか？ 本人とサインインも一緒に削除されます。操作の履歴・割り当て・証明書が無いアカウントだけ削除できます。それ以外はアクセスを取り消してください。",
  "This account has acted or has an assignment or certificate, so it cannot be deleted — revoke the access instead": "このアカウントは操作の履歴、割り当て、または証明書があるため削除できません。代わりにアクセスを取り消してください",
