  "Delete {name}? An IoT model that units or devices use, or that a firmware campaign names, cannot be deleted.": "{name} を削除しますか？ユニットやデバイスが使っている、またはファームウェア配信に名前のあるIoT機種は削除できません。",
  "No aircon models": "エアコン機種はありません",
