  "Choose an IoT model": "IoT機種を選択してください",
  "Choose the device, or leave it out": "デバイスを選択するか、指定しないでください",
  "Connect device…": "デバイスを接続…",
  "Connect to AC unit · optional": "ACユニットに接続 · 任意",
  "Device connected — the previous device on the unit was unbound": "デバイスを接続しました — ユニット上の前のデバイスは解除されました",
  "Device registered and connected to the unit": "デバイスを登録し、ユニットに接続しました",
  "Device registered — connect it to a unit when it is installed": "デバイスを登録しました — 設置したらユニットに接続してください",
  "Device registered, but not connected to the unit — connect it from its page": "デバイスは登録されましたがユニットに接続できませんでした — デバイスのページから接続してください",
  "Device registered, but not connected — connect it again from here": "デバイスは登録されましたが接続できませんでした — ここからもう一度接続してください",
  "Device serial": "デバイスのシリアル",
  "Devices not on a unit. Its IoT model and node ID are kept as registered.": "ユニットに接続されていないデバイス。IoT機種とノードIDは登録どおりに保たれます。",
  "IoT model · sensors": "IoT機種 · センサ",
  "Leave it empty to register the device on its own (a spare, or one not installed yet). Only units without a device are listed.": "空のままにするとデバイス単体で登録されます（予備機、または未設置）。デバイスのないユニットのみ表示されます。",
  "No device": "デバイスなし",
