  "No temperature sensor: temperature cannot be measured for this device.": "温度センサがありません：このデバイスでは温度を測定できません。",
  "Not connected": "未接続",
  "Now": "現在",
  "On {unit} — move it from its page": "{unit}に接続中 — デバイスのページから付け替えてください",
  "Optional: connect the unit's IoT device now — one already registered, or a new one. It can also be connected later from the unit's page.": "任意：ユニットのIoTデバイスを今接続します（登録済みのもの、または新規）。後でユニットのページから接続することもできます。",
  "Register a new device": "新しいデバイスを登録",
  "Registered device": "登録済みデバイス",
  "Replace…": "交換…",
  "The device leaves its unit and stays registered; history stays with the binding, and the unit has no device until you connect another.": "デバイスはユニットから外れ、登録は残ります。履歴は接続に残り、別のデバイスを接続するまでユニットにデバイスはありません。",
  "The device's IoT model sets its sensors; it is shown here as registered. The aircon model above is the unit's own.": "デバイスのIoT機種がセンサを決めます。ここには登録どおりに表示されます。上のエアコン機種はユニット自身のものです。",
  "Unit “{name}” registered, but its device was not connected: {reason} — connect it from the unit’s page": "ユニット「{name}」は登録されましたが、デバイスを接続できませんでした：{reason} — ユニットのページから接続してください",
  "Units of every customer in your scope; the customer, place and aircon model are shown beside the name.": "担当範囲のすべての顧客のユニット。顧客・設置場所・エアコン機種が名前の横に表示されます。",
  "What the device measures comes from this model; it is not the aircon model of the unit.": "デバイスが測定する内容はこの機種で決まります。ユニットのエアコン機種ではありません。",
  "{serial} is on this unit now. Connecting replaces it: it is unbound, and its history stays with it.": "{serial}は現在このユニットに接続されています。接続すると交換され、前のデバイスは解除されます（履歴は残ります）。",
  "{serial} is on this unit now. It is unbound in the same step and keeps its history; the unit has the new device only if both steps succeed.": "{serial}は現在このユニットに接続されています。同じ操作で解除され、履歴は残ります。両方が成功した場合にのみ新しいデバイスが接続されます。",
  "Installations": "設置申請",
  "Not decided": "未定",
  "A whole number of 1–{max}": "1〜{max}の整数",
  "A reason of {min}–{max} characters": "{min}〜{max}文字の理由",
  "Installation requests": "設置申請",
  "Ask HQ to install new air conditioners, with or without an IoT device. HQ plans the units and offers a visit time.": "新しいエアコンの設置をHQに依頼します（IoT機器の有無を選べます）。HQがユニットを計画し、訪問時間を提案します。",
  "with an IoT device": "IoT機器あり",
  "without an IoT device": "IoT機器なし",
  "HQ: {reason}": "HQの理由：{reason}",
  "First preferred time": "第1希望の日時",
  "HQ creates the units and the installation jobs, or declines with a reason. You can’t change a request; cancel it and send a new one. Only owners see this page.": "HQがユニットと設置ジョブを作成するか、理由を付けて却下します。申請は変更できません。取り消して新しく送ってください。このページはオーナーだけに表示されます。",
